return {["scripts/actions/abilities/pets/recoil_dive.lua"]={["Path"]="scripts/actions/abilities/pets/recoil_dive.lua",["SHA256"]="6fdcf979840492cb7af89e11692ea5f37bcc5712eeb264f5bff57e357a97208f",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'recoil_dive_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/regal_scratch.lua"]={["Path"]="scripts/actions/abilities/pets/regal_scratch.lua",["SHA256"]="f9f251c3f1102328644f792979c02767c39039c2bbb21a367e90720ca4662759",["Text"]="-----------------------------------\n-- Regal Scratch\n-- Family: Avatar (Cait Sith)\n-- Description: Delivers a threefold attack.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    -- https://wiki.ffo.jp/html/26384.html\n    -- JP Wiki states that this skill was excluded from carrying first hit fTP to subsequent hits.\n    -- (See Patch note history for November 10th, 2016 in above link.)\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 3\n    params.fTP               = { 3.00, 3.00, 3.00 } -- TODO: Capture fTPs\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    -- params.dex_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_3\n    -- params.accuracyModifier   = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/remove_blindness.lua"]={["Path"]="scripts/actions/abilities/pets/remove_blindness.lua",["SHA256"]="c99b249a84b1b475f84977e93ee8c963b5a0bd10dad031a0d9e2b63b6300ba12",["Text"]="-----------------------------------\n-- Remove Blindness\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    if target:delStatusEffect(xi.effect.BLINDNESS) then\n        petskill:setMsg(xi.msg.basic.JA_REMOVE_EFFECT)\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT)\n    end\n\n    return xi.effect.BLINDNESS\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/remove_curse.lua"]={["Path"]="scripts/actions/abilities/pets/remove_curse.lua",["SHA256"]="6fc7634e3c9c4fb351dc08498012e9ac2bc9adbc354f0c8eea2f3bc2d07ac37d",["Text"]="-----------------------------------\n-- Remove Curse\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local effect\n    if target:delStatusEffect(xi.effect.CURSE_I) then\n        petskill:setMsg(xi.msg.basic.JA_REMOVE_EFFECT)\n        effect = xi.effect.CURSE_I\n    elseif target:delStatusEffect(xi.effect.DOOM) then\n        petskill:setMsg(xi.msg.basic.JA_REMOVE_EFFECT)\n        effect = xi.effect.DOOM\n    elseif target:delStatusEffect(xi.effect.BANE) then\n        petskill:setMsg(xi.msg.basic.JA_REMOVE_EFFECT)\n        effect = xi.effect.BANE\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT)\n    end\n\n    return effect\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/remove_disease.lua"]={["Path"]="scripts/actions/abilities/pets/remove_disease.lua",["SHA256"]="b6cf144a5a99f83cfa6514bbe2f17e4aa61798abb5d431cc5f2e85feba1da8b5",["Text"]="-----------------------------------\n-- Remove Disease\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local effect\n    if target:delStatusEffect(xi.effect.DISEASE) then\n        petskill:setMsg(xi.msg.basic.JA_REMOVE_EFFECT)\n        effect = xi.effect.DISEASE\n    elseif target:delStatusEffect(xi.effect.PLAGUE) then\n        petskill:setMsg(xi.msg.basic.JA_REMOVE_EFFECT)\n        effect = xi.effect.PLAGUE\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT)\n    end\n\n    return effect\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/remove_paralysis.lua"]={["Path"]="scripts/actions/abilities/pets/remove_paralysis.lua",["SHA256"]="9dfcf035dbebb5fca3eaa3eab3190c61c17705a83faee89803a2e0e3fc8206c3",["Text"]="-----------------------------------\n-- Remove Paralysis\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    if target:delStatusEffect(xi.effect.PARALYSIS) then\n        petskill:setMsg(xi.msg.basic.JA_REMOVE_EFFECT)\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT)\n    end\n\n    return xi.effect.PARALYSIS\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/remove_poison.lua"]={["Path"]="scripts/actions/abilities/pets/remove_poison.lua",["SHA256"]="c2ff236263bddfaf46c94eb0823dfcf8b385ab562ac2bef3e18d95e87ec5be18",["Text"]="-----------------------------------\n-- Remove Poison\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    if target:delStatusEffect(xi.effect.POISON) then\n        petskill:setMsg(xi.msg.basic.JA_REMOVE_EFFECT)\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT)\n    end\n\n    return xi.effect.POISON\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/reraise_ii.lua"]={["Path"]="scripts/actions/abilities/pets/reraise_ii.lua",["SHA256"]="5890137e25f330f0b4536f9ab13ebba0aadcb28239302548d2d97fa5f1ad7356",["Text"]="-----------------------------------\n-- Reraise II\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    if\n        not target:isPC() or\n        not target:addStatusEffect(xi.effect.RERAISE, { power = 2, duration = 3600, origin = pet })\n    then\n        petskill:setMsg(xi.msg.basic.NO_EFFECT)\n        return 0\n    end\n\n    petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n\n    return xi.effect.RERAISE\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/rhino_attack.lua"]={["Path"]="scripts/actions/abilities/pets/rhino_attack.lua",["SHA256"]="097ff750f05d77675e6751836889ecac850613e7a9e7314e75b385c86ee90974",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'rhino_attack_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/rhino_guard.lua"]={["Path"]="scripts/actions/abilities/pets/rhino_guard.lua",["SHA256"]="ea910f64a212d6a071f6ff1674a78c58f8748137086881f11bba9ca6d006c4d7",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'rhino_guard_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/rhinowrecker.lua"]={["Path"]="scripts/actions/abilities/pets/rhinowrecker.lua",["SHA256"]="2d1c2af8d60c38288d809e29574cb90a0f79469733e50889a0049c8716320627",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    -- TODO implement this ability\n    return xi.msg.basic.PET_CANNOT_DO_ACTION\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/ripper_fang.lua"]={["Path"]="scripts/actions/abilities/pets/ripper_fang.lua",["SHA256"]="5dfab6f488686a5748b3deda4114e2c7940f8a950167a3c3f50dc4eafcf6a92e",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'ripper_fang_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/roar.lua"]={["Path"]="scripts/actions/abilities/pets/roar.lua",["SHA256"]="12010adae1f0618a014cf6874d8ef9cd9c73204d3f33cf4c510d26e2e0e5513d",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'roar_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/rock_buster.lua"]={["Path"]="scripts/actions/abilities/pets/rock_buster.lua",["SHA256"]="80fb7c281fa968f4c0544352b17a4e68eb87f6973def5fefcb7613c778c886f0",["Text"]="-----------------------------------\n-- Rock Buster\n-- Family: Avatar (Titan)\n-- Description: Deals physical damage to a target. Additional Effect: Bind\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.25, 4.50, 6.75 } -- TODO: Capture fTP for 2000TP\n    params.fTPSubsequentHits = { 2.25, 4.50, 6.75 }\n    params.vit_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.BIND, power = 1, duration = 120 }, -- TODO: Capture duration\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/rock_throw.lua"]={["Path"]="scripts/actions/abilities/pets/rock_throw.lua",["SHA256"]="549b3cbdef709cfbb61df90aa42aed3b43a6b8b52fbe50834cd9eed6f3f70333",["Text"]="-----------------------------------\n-- Rock Throw\n-- Family: Avatar (Titan)\n-- Description: Delivers a ranged attack to a target. Additional Effect: Slow\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getRangedDmg()\n    params.numHits           = 1\n    params.fTP               = { 1.0, 1.0, 1.0 }\n    params.fTPSubsequentHits = { 1.0, 1.0, 1.0 }\n    params.str_wSC           = 0.20\n    params.agi_wSC           = 0.20\n    params.skipParry         = true\n    params.skipGuard         = true\n    params.skipBlock         = true\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    -- params.accuracyModifier   = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobRangedMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.SLOW, power = 3000, duration = 120, tier = 8 }, -- TODO: Capture Slow tier\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/rolling_thunder.lua"]={["Path"]="scripts/actions/abilities/pets/rolling_thunder.lua",["SHA256"]="6d2de8b7c773e857cb339ecc0704f2eda200760eac3d9432054a1599f04f6c5b",["Text"]="-----------------------------------\n-- Rolling Thunder\n-- Family: Avatar (Ramuh)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    local baseDuration = 120\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local magicskill = xi.data.skillLevel.getSkillCap(target:getMainLvl(), xi.skillRank.A_PLUS)\n    local potency    = 3 + 6 * magicskill / 100\n\n    if magicskill > 200 then\n        potency = 5 + 5 * magicskill / 100\n    end\n\n    xi.mobskills.mobBuffMove(target, xi.effect.ENTHUNDER, potency, 0, duration)\n\n    if target:getID() == action:getPrimaryTargetID() then\n        petskill:setMsg(xi.msg.basic.JA_RECEIVES_EFFECT_2)\n    else\n        petskill:setMsg(xi.msg.basic.JA_RECEIVES_EFFECT)\n    end\n\n    return xi.effect.ENTHUNDER\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/roundhouse.lua"]={["Path"]="scripts/actions/abilities/pets/roundhouse.lua",["SHA256"]="5e619e08a06250617972595a8979b40cfb93720236fea436e66278fb8e6924f9",["Text"]="-----------------------------------\n-- Roundhouse\n-- Family: Avatar (Siren)\n-- Description: Deals physical damage to a target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\n-- http://wiki.ffo.jp/html/37928.html\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 5.0, 5.0, 5.0 } -- TODO: Capture fTPs\n    params.fTPSubsequentHits = { 5.0, 5.0, 5.0 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.canCrit           = true\n    params.criticalChance    = { 0.10, 0.20, 0.25 } -- TODO: Capture crit rate\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/rush.lua"]={["Path"]="scripts/actions/abilities/pets/rush.lua",["SHA256"]="62f1a028c7a265e760c67b55242ca53e3e04ef387a306e98e2f4affbe5fac5ce",["Text"]="-----------------------------------\n-- Rush\n-- Family: Avatar (Shiva)\n-- Description: Delivers a fivefold attack to a target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 5\n    params.fTP               = { 3.5, 3.5, 3.5 }\n    params.fTPSubsequentHits = { 3.5, 3.5, 3.5 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_5\n    -- params.accuracyModifier = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/sand_breath.lua"]={["Path"]="scripts/actions/abilities/pets/sand_breath.lua",["SHA256"]="c1c9c77e2af9f84e3d230a475a1dcfe3bbf5f0d6b8993780ea8023af60d5b03f",["Text"]="-----------------------------------\n-- Sand Breath\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    return xi.job_utils.dragoon.useDamageBreath(pet, target, petskill, action, xi.damageType.EARTH)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/sandblast.lua"]={["Path"]="scripts/actions/abilities/pets/sandblast.lua",["SHA256"]="d48733b5e92e11439199ab2cadaad3f5908fdb4591318b0a78e15e6a885f71a6",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'sandblast_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/sandpit.lua"]={["Path"]="scripts/actions/abilities/pets/sandpit.lua",["SHA256"]="c0fa95dab7633ff9c12fdef5b77810750e944b7b5c4ca421eadc325e102bb8d9",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'sandpit_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/scissor_guard.lua"]={["Path"]="scripts/actions/abilities/pets/scissor_guard.lua",["SHA256"]="7511de5739f9c1764bbae3cd8ec18ec1bf54aec5a628afa872c834464c15ae1a",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'scissor_guard_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/scream.lua"]={["Path"]="scripts/actions/abilities/pets/scream.lua",["SHA256"]="50853755776d9363a96c0ea9c7e1a116b6c505dd11d5da3440ca1c918f62d547",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'scream_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/scythe_tail.lua"]={["Path"]="scripts/actions/abilities/pets/scythe_tail.lua",["SHA256"]="5779f6e389137ff28a710166d80c62f5126d7ac53ed4cdebfa94a1ed2b2e88b1",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'scythe_tail_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/searing_light.lua"]={["Path"]="scripts/actions/abilities/pets/searing_light.lua",["SHA256"]="cb200427fed9cf3e433e7d13183943268bc33070d347c626642c067543a9f42a",["Text"]="-----------------------------------\n-- Searing Light\n-- Family: Carbuncle (Player Pet)\n-- Note: Carbuncle's Astral Flow\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 7.9765, 7.9765, 7.9765 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.LIGHT\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.LIGHT\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n    -- TODO: Should not consume TP\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    summoner:setMP(0)\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/secretion.lua"]={["Path"]="scripts/actions/abilities/pets/secretion.lua",["SHA256"]="f035eda68ab3cd93b7b438c39d25ab081c0a1d307d4542d28a09ce33764b37f0",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'secretion_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/shakeshroom.lua"]={["Path"]="scripts/actions/abilities/pets/shakeshroom.lua",["SHA256"]="73e294ec48011bf6511226833aba54589280147069fcd098ff34d00076558e63",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'shakeshroom_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    local pet = player:getPet()\n    local checkResult = xi.actions.mobskills[skillName].onMobSkillCheck(target, pet, ability)\n    if checkResult ~= 0 then\n        return xi.msg.basic.PET_CANNOT_DO_ACTION, 0 -- TODO: verify exact message in packet.\n    end\n\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/sheep_charge.lua"]={["Path"]="scripts/actions/abilities/pets/sheep_charge.lua",["SHA256"]="a47607300d2535f5c74f6f95be2943bfe626402cafb131aa4415cce958b462f4",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'sheep_charge_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/sheep_song.lua"]={["Path"]="scripts/actions/abilities/pets/sheep_song.lua",["SHA256"]="4e9e6cfcd7901e9ca517d6f442f14cf84e97f405574bc468811b0873dbc92fc8",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'sheep_song_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/shining_ruby.lua"]={["Path"]="scripts/actions/abilities/pets/shining_ruby.lua",["SHA256"]="03666bdf934c34bdd76496dd3718a9725f8258b29e963de092b1c6cd678e68df",["Text"]="-----------------------------------\n-- Shining Ruby\n-- Family: Avatar (Carbuncle)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- TODO: BGWiki says this shares a buff slot with Rampart, Winds Blessing and One For All.\n    -- Need to capture tier priority.\n    -- https://www.bg-wiki.com/ffxi/Shining_Ruby\n    if target:hasStatusEffect(xi.effect.SHINING_RUBY) then\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT)\n\n        return xi.effect.SHINING_RUBY\n    end\n\n    local baseDuration = 180\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n\n    target:addStatusEffect(xi.effect.SHINING_RUBY, { power = 10, subPower = 390, duration = duration, origin = pet })\n\n    if target:getID() == action:getPrimaryTargetID() then\n        petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n    else\n        petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n    end\n\n    return xi.effect.SHINING_RUBY\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/shock_strike.lua"]={["Path"]="scripts/actions/abilities/pets/shock_strike.lua",["SHA256"]="403565a227fd7ec43ebcc1d0ebcc2119f9ab16bc59317d59b5163ab4fe68232e",["Text"]="-----------------------------------\n-- Shock Strike\n-- Family: Avatar (Ramuh)\n-- Description: Deals physical damage to a target. Additional Effect: Stun\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.0, 2.0, 2.0 }\n    params.fTPSubsequentHits = { 2.0, 2.0, 2.0 }\n    params.str_wSC           = 0.20\n    params.int_wSC           = 0.20\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.canCrit           = true\n    params.criticalChance    = { 0.10, 0.20, 0.25 } -- TODO: Capture crit rate\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.STUN, power = 1, duration = 12 },\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/silence_gas.lua"]={["Path"]="scripts/actions/abilities/pets/silence_gas.lua",["SHA256"]="c5d50b3a23d848b458510ae25f3ab4612a0a97e37976a8ca327c97eb82c9f85b",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'silence_gas_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"}};
